/bin/zsh -lc "cd /var/tmp/loop-bench/runs/5e64b784e4ec/workspace/target && cat > src/transport/ws/listSessionsValidation.test.ts <<'EOF'
import {validateMessage} from './validation.js';

// specs/hal-engine-websocket-protocol/spec.md#list-sessions-validation
it('validates list_sessions pagination and strips unknown fields', () => {
  expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  expect(validateMessage({type: 'list_sessions', limit: 0, before: {sessionId: 's', updatedAt: 0}, userId: 'other'})).toEqual({
    valid: true, data: {type: 'list_sessions', limit: 0, before: {sessionId: 's', updatedAt: 0}},
  });
  for (const limit of [-1, 1.5, '1']) {
    expect(validateMessage({type: 'list_sessions', limit})).toMatchObject({valid: false, error: expect.stringContaining('limit')});
  }
  for (const before of [null, {}, {sessionId: '', updatedAt: 0}, {sessionId: 'x'.repeat(129), updatedAt: 0}, {sessionId: 's', updatedAt: 'bad'}, {sessionId: 's', updatedAt: Infinity}]) {
    expect(validateMessage({type: 'list_sessions', before})).toMatchObject({valid: false, error: expect.stringContaining('before')});
  }
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/transport/ws/listSessionsValidation.test.ts"

